const WALK_AUDIO={"voice":"af_heart","speed":0.9,"lines":{"intro":{"t":"This is the daily data sheet. Each row is one school day, and each column is one behavior the plan is tracking. A few numbers at the end of each day become the graphs the team uses to decide whether the plan is working.","d":14.56,"a":"data:audio/mpeg;base64,"},"types":{"t":"The colored bands group the columns. Reduction targets are the behaviors the plan aims to decrease. Replacement behaviors are what the student does instead, for the same outcome, and they should rise as the targets fall. Acquisition targets are skills taught to a mastery criterion.","d":18.699,"a":"data:audio/mpeg;base64,"},"defs":{"t":"Every column has a number. Its definition, and how it is measured, are below the sheet under the same number, so everyone who records counts the same thing.","d":10.4,"a":"data:audio/mpeg;base64,"},"units":{"t":"The row under the names says what goes in each column: a count for the day, the total minutes for a behavior measured by duration, or the correct responses and the opportunities for a skill.","d":12.149,"a":"data:audio/mpeg;base64,"},"day":{"t":"At the end of the day, write the date and fill in the row: one number in each column, from your tally or your timer.","d":6.88,"a":"data:audio/mpeg;base64,"},"obsmin":{"t":"Observation minutes are how long you watched. They fill in from the school day. If the student arrived late or left early, type the minutes you actually had, so the rate stays fair.","d":11.381,"a":"data:audio/mpeg;base64,"},"blankzero":{"t":"Leave a cell blank when you did not measure that behavior. Write a zero when you measured it and it did not happen. They mean different things, and the graph treats them differently.","d":10.08,"a":"data:audio/mpeg;base64,"},"episodes":{"t":"For a behavior measured by duration, you can log each episode on its own: when it started and when it stopped. The form adds them up for the day.","d":9.696,"a":"data:audio/mpeg;base64,"},"percent":{"t":"For a skill, write how many responses were correct and how many chances there were. The form works out the percent.","d":7.029,"a":"data:audio/mpeg;base64,"},"phase":{"t":"When the plan changes, mark a full phase change on the first day of the new plan, and name the new condition. The graph starts a new section from that day.","d":9.483,"a":"data:audio/mpeg;base64,"},"cond":{"t":"For an event inside a phase, such as a medication change, a new staff member, or an illness, mark a conditional change. It adds a dashed line to the graph without splitting the phase.","d":11.936,"a":"data:audio/mpeg;base64,"},"graph":{"t":"Each behavior gets its own graph. Every point is a day. The solid line is the phase change, and each phase gets its own level and its own trend line.","d":10.187,"a":"data:audio/mpeg;base64,"},"analysis":{"t":"Under each graph, the form compares the phases: how much the level changed, which way the trend is going, how much the data vary, and how far the phases overlap. The team reads the graph first, and the numbers with it.","d":14.539,"a":"data:audio/mpeg;base64,"},"adults":{"t":"A few habits keep the data worth reading. Record the same way every day. Keep blank and zero apart. Mark changes on the day they happen. And save the file to the student's folder.","d":12.107,"a":"data:audio/mpeg;base64,"},"outro":{"t":"One row a day, the same way every day. That is what makes the graph tell the truth.","d":5.323,"a":"data:audio/mpeg;base64,"}}};
